def shortest_path(graph, source, target):
    # Initialize distances and paths
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    path = {node: None for node in graph}

    # Priority queue for BFS, initialized with the source node
    queue = [(0, source)]

    while queue:
        current_distance, current_node = queue.pop(0)  # Dequeue

        # If we reached the target, return the path
        if current_node == target:
            path_nodes = []
            while current_node:
                path_nodes.append(current_node)
                current_node = path[current_node]
            path_nodes.reverse()
            return (current_distance, path_nodes)

        # Explore neighbors
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # Check if a better path to neighbor was found
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                path[neighbor] = current_node
                # Enqueue the neighbor with the new distance
                queue.append((distance, neighbor))

    # If we exited the loop without returning, the target is unreachable
    return (float('inf'), None)

