def shortest_path(graph, source, target):
    # Building the initial shortest distances dictionary
    distances = {node: float('inf') for node in graph}
    distances[source] = 0

    # Building the initial previous nodes dictionary
    previous = {node: None for node in graph}

    # Our queue allowing to test all the nodes
    queue = [source]

    # As long as we have nodes in our queue
    while queue:
        current = queue.pop(0)

        # For each neighbor of the current node
        for neighbor, weight in graph.get(current, []):
            # If we find a shorter path to reach the neighbor
            if distances[current] + weight < distances[neighbor]:
                distances[neighbor] = distances[current] + weight
                previous[neighbor] = current
                # Adding the neighbor to our queue
                queue.append(neighbor)

                # If we reach the target, we can stop the search
                if neighbor == target:
                    path = [neighbor]
                    while previous[neighbor] is not None:
                        neighbor = previous[neighbor]
                        path.append(neighbor)
                    path.reverse()
                    return (distances[target], path)

    # If we have not reached the target, we return infinity and None
    return (float('inf'), None)
