    if distances[source] == float('inf'):
        return float('inf'), None

    path = [target]
    while path[-1] != source:
        for neighbor, weight in graph[path[-1]]:
            if distances[path[-1]] + weight == distances[neighbor]:
                path.append(neighbor)
                break
    path.reverse()

    return distances[source], path

